import json
import csv
import os

def get_cvss_score(vuln_data):
    """
    Extract CVSS v3 score from vulnerability data.
    Uses priority: NVD > GHSA > RedHat
    """
    cvss = vuln_data.get('CVSS', {})
    if not cvss:
        return 'N/A'

    # Priority 1: NVD
    if 'nvd' in cvss:
        score = cvss['nvd'].get('V3Score')
        if score is not None:
            return score

    # Priority 2: GHSA
    if 'ghsa' in cvss:
        score = cvss['ghsa'].get('V3Score')
        if score is not None:
            return score

    # Priority 3: RedHat
    if 'redhat' in cvss:
        score = cvss['redhat'].get('V3Score')
        if score is not None:
            return score

    return 'N/A'

def process_trivy_report(input_file, output_file):
    if not os.path.exists(input_file):
        print(f"Error: {input_file} not found.")
        return

    with open(input_file, 'r', encoding='utf-8') as f:
        data = json.load(f)

    vulnerabilities = []

    if 'Results' in data:
        for result in data['Results']:
            if 'Vulnerabilities' in result:
                for vuln in result['Vulnerabilities']:
                    severity = vuln.get('Severity', 'UNKNOWN')
                    if severity in ['HIGH', 'CRITICAL']:
                        record = {
                            "Package": vuln.get('PkgName'),
                            "Version": vuln.get('InstalledVersion'),
                            "CVE_ID": vuln.get('VulnerabilityID'),
                            "Severity": severity,
                            "CVSS_Score": get_cvss_score(vuln),
                            "Fixed_Version": vuln.get('FixedVersion', 'N/A'),
                            "Title": vuln.get('Title') or vuln.get('Description', 'No description'),
                            "Url": vuln.get('PrimaryURL', 'N/A')
                        }
                        # Ensure empty Fixed_Version is N/A
                        if not record["Fixed_Version"]:
                            record["Fixed_Version"] = "N/A"
                        vulnerabilities.append(record)

    headers = ["Package", "Version", "CVE_ID", "Severity", "CVSS_Score", "Fixed_Version", "Title", "Url"]

    with open(output_file, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=headers)
        writer.writeheader()
        writer.writerows(vulnerabilities)

    print(f"Successfully processed {len(vulnerabilities)} HIGH/CRITICAL vulnerabilities.")

if __name__ == "__main__":
    process_trivy_report('/root/trivy_report.json', '/root/security_audit.csv')

